module codex_utils_fuzzy_match

// Unicode 17.0.0 lowercase mappings and Final_Sigma classifications, generated from
// Rust char::to_lowercase and str::to_lowercase (rustc 1.97.1, Unicode 17.0.0).
// Scalar records contain four six-digit hex values: original and up to three lowercase
// scalars. Range records contain inclusive six-digit endpoints. The cased table excludes
// case-ignorable scalars, which Final_Sigma skips before asking whether a scalar is cased.
// These local data retain full Rust lowercase behavior without a runtime Rust dependency.

const lowercase_mappings = ''

const case_ignorable_ranges = ''

const non_ignorable_cased_ranges = ''
